contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(
        uint256 nonce,
        uint256 strike,
        uint256 premium,
        uint256 duration,
        uint256 expiration
    ) public {
        C.Order memory order = C.Order({
            maker: address(this),
            isCall: false,
            isLong: true,
            baseAsset: address(0x1111),
            strike: strike,
            premium: premium,
            duration: duration,
            expiration: expiration,
            nonce: nonce,
            whitelist: new address[](0),
            floorTokens: new address[](0),
            erc20Assets: new C.ERC20Asset[](0),
            erc721Assets: new C.ERC721Asset[](0)
        });

        bytes32 longHash = c.hashOrder(order);

        C.Order memory opposite = C.Order({
            maker: address(this),
            isCall: false,
            isLong: false,
            baseAsset: address(0x1111),
            strike: strike,
            premium: premium,
            duration: duration,
            expiration: expiration,
            nonce: nonce,
            whitelist: new address[](0),
            floorTokens: new address[](0),
            erc20Assets: new C.ERC20Asset[](0),
            erc721Assets: new C.ERC721Asset[](0)
        });

        bytes32 shortHash = c.hashOrder(opposite);

        assert(longHash != shortHash && uint256(longHash) != 0 && uint256(shortHash) != 0);
    }
}

