contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(
        address maker,
        bool isCall,
        bool isLong,
        address baseAsset,
        uint256 strike,
        uint256 premium,
        uint256 duration,
        uint256 expiration,
        uint256 nonce
    ) public payable {
        require(maker != address(0), "maker zero");
        require(baseAsset != address(0), "baseAsset zero");

        C.Order memory order = C.Order({
            maker: maker,
            isCall: isCall,
            isLong: isLong,
            baseAsset: baseAsset,
            strike: strike,
            premium: premium,
            duration: duration,
            expiration: expiration,
            nonce: nonce,
            whitelist: new address[](0),
            floorTokens: new address[](0),
            erc20Assets: new C.ERC20Asset[](0),
            erc721Assets: new C.ERC721Asset[](0)
        });

        bytes32 orderHash = c.hashOrder(order);

        bool beforeFlag = c.cancelledOrders(orderHash);
        bool reverted;
        try c.cancel(order) {
            reverted = false;
        } catch {
            reverted = true;
        }
        bool afterFlag = c.cancelledOrders(orderHash);

        if (msg.sender == maker) {
            assert(!reverted);
            assert(afterFlag == true && beforeFlag == false);
        } else {
            assert(reverted);
            assert(afterFlag == beforeFlag);
        }
    }

    receive() external payable {}
}

contract InvMutTest {
