            baseAsset: baseAsset,
            strike: strike,
            premium: premium,
            duration: duration,
            expiration: expiration,
            nonce: nonce,
            whitelist: new address[](0),
            floorTokens: new address[](0),
            erc20Assets: new C.ERC20Asset[](0),
            erc721Assets: new C.ERC721Asset[](0)
        });

        bytes32 orderHash = c.hashOrder(order);

        bool beforeFlag = c.cancelledOrders(orderHash);

        bool firstReverted;
        try c.cancel(order) {
            firstReverted = false;
        } catch {
            firstReverted = true;
        }

        bool afterFirstFlag = c.cancelledOrders(orderHash);

        bool secondReverted;
        try c.cancel(order) {
            secondReverted = false;
        } catch {
            secondReverted = true;
        }

        bool afterSecondFlag = c.cancelledOrders(orderHash);

