contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(
        uint256 orderNonce,
        address maker,
        uint256 strike,
        uint256 premium,
        uint256 duration,
        uint256 expiration,
        uint256 wrongAmount,
        bool sendWrongAmount
    ) public payable {
        require(expiration > block.timestamp);
        require(duration < 10_000 days);
        require(strike > 0);
        require(wrongAmount > 0);
        require(premium > 0);

        // Use Putty's own WETH token as the base asset so we can freely wrap ETH and mint test tokens.
        IWETH weth = IWETH(c.weth());

        if (sendWrongAmount) {
            weth.deposit{value: strike}();
            weth.transfer(address(this), wrongAmount);
        } else {
            weth.deposit{value: strike}();
        }

        require(weth.balanceOf(address(this)) >= strike);
        weth.approve(address(c), strike + 1);

        C.Order memory order = C.Order({
            maker: address(this),
            isCall: false,
            isLong: false,
            baseAsset: address(weth),
            strike: strike,
            premium: premium,
            duration: duration,
            expiration: expiration,
            nonce: orderNonce,
            whitelist: new address[](0),
            floorTokens: new address[](0),
            erc20Assets: new C.ERC20Asset[](0),
            erc721Assets: new C.ERC721Asset[](0)
        });

        bytes memory dummySig = new bytes(0);
        uint256[] memory emptyFloor = new uint256[](0);

        bool reverted;
        try c.fillOrder(order, dummySig, emptyFloor) returns (uint256) {
            reverted = false;
        } catch {
            reverted = true;
        }

        assert(reverted == sendWrongAmount);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(
        uint256 nonce,
        uint256 strike,
        uint256 premium,
        uint256 duration,
        uint256 expiration,
        uint256 fundedAmount,
        bool fundLess
    ) public payable {
        require(expiration > block.timestamp, "expiration must be future");
        require(duration < 10_000 days, "duration too long");
        require(strike > 0, "strike must be positive");
        require(premium > 0, "premium must be positive");
        require(fundedAmount >= strike, "fundedAmount must be >= strike");

        // Use Putty's own WETH as the base asset so the maker can provide locked funds.
        IWETH weth = IWETH(c.weth());

        // Maker (this contract) wraps ETH into WETH.
        weth.deposit{value: fundLess ? strike - 1 : fundedAmount}();

        // Approve the Putty contract to pull the strike amount during fillOrder.
        require(weth.approve(address(c), strike), "approve failed");

        C.Order memory order = C.Order({
            maker: address(this),
            isCall: false,
            isLong: false,
            baseAsset: address(weth),
            strike: strike,
            premium: premium,
            duration: duration,
            expiration: expiration,
            nonce: nonce,
            whitelist: new address[](0),
            floorTokens: new address[](0),
            erc20Assets: new C.ERC20Asset[](0),
            erc721Assets: new C.ERC721Asset[](0)
        });

        bytes memory dummySig = new bytes(0);
        uint256[] memory emptyFloor = new uint256[](0);

        bool reverted;
        try c.fillOrder(order, dummySig, emptyFloor) returns (uint256) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // The fill must revert exactly when the contract was funded with less than strike.
        assert(reverted == fundLess);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(
        uint256 nonce,
        uint256 strike,
        uint256 premium,
        uint256 duration,
        uint256 expiration,
        uint256 fundedAmount
    ) public payable {
        require(expiration > block.timestamp, "expiration must be future");
        require(duration < 10_000 days, "duration too long");
        require(strike > 0, "strike must be positive");
        require(premium > 0, "premium must be positive");
        require(fundedAmount > 0, "fundedAmount must be positive");

        IWETH weth = IWETH(c.weth());

        weth.deposit{value: fundedAmount}();

        bool approved = weth.approve(address(c), strike);
        require(approved, "approve failed");

        C.Order memory order = C.Order({
            maker: address(this),
            isCall: false,
            isLong: false,
            baseAsset: address(weth),
            strike: strike,
            premium: premium,
            duration: duration,
            expiration: expiration,
            nonce: nonce,
            whitelist: new address[](0),
            floorTokens: new address[](0),
            erc20Assets: new C.ERC20Asset[](0),
            erc721Assets: new C.ERC721Asset[](0)
        });

        bytes memory dummySig = new bytes(0);
        uint256[] memory emptyFloor = new uint256[](0);

        bool reverted;
        try c.fillOrder(order, dummySig, emptyFloor) returns (uint256) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // For a short put fill, the maker must have at least strike funds available.
        assert(reverted == (fundedAmount < strike));
    }

    receive() external payable {}
}

