contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 id, address to) public {
        require(to != address(0), "to must not be zero");
        address expectedFrom = c.ownerOf(id);
        address testContract = address(this);
        bool authorized = (expectedFrom == testContract) || c.isApprovedForAll(expectedFrom, testContract) || (c.getApproved(id) == testContract);
        bool reverted;
        try c.transferFrom(expectedFrom, to, id) {
            reverted = false;
        } catch {
            reverted = true;
        }
        if (authorized) {
            assert(!reverted && c.ownerOf(id) == to);
        } else {
            assert(reverted && c.ownerOf(id) == expectedFrom);
        }
    }
}

